using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;
public sealed class CannonTotalTests:MonoBehaviour {
 public static bool PreviewOnly;public static int bounceChoice;static int bounces;static Vector2 bouncePosition;static string blocker;static bool blocked;static bool equalChance=true;
 public static bool WantBounce(float chance){equalChance &= Mathf.Abs(chance-.5f)<.0001f;return bounceChoice>0;}
 public static void Bounced(Component actor,Vector2 position,Vector2 velocity){bounces++;bouncePosition=position;Debug.Log("BOUNCE CONTACT actor="+actor.name+" at="+position+" velocity="+velocity);}
 public static void WorldContact(Collision2D c){Component a=c.collider.GetComponentInParent<BuildPlayer>();Component d=c.otherCollider.GetComponentInParent<BuildPlayer>();if((a!=null&&a.name==blocker)||(d!=null&&d.name==blocker))blocked=true;}
 public static bool UseAI;static bool booted;static HashSet<KeyCode> keys=new HashSet<KeyCode>();static Dictionary<KeyCode,int> frames=new Dictionary<KeyCode,int>();
 public static bool ReadKey(KeyCode k){return keys.Contains(k);}public static bool ReadDown(KeyCode k){if(!keys.Contains(k))return false;int f;if(!frames.TryGetValue(k,out f)){frames[k]=Time.frameCount;return true;}return f==Time.frameCount;}
 public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=System.IO.Path.Combine(Application.dataPath,"..","cannon-test.ini");var o=new GameObject("CannonTotalTests");DontDestroyOnLoad(o);o.AddComponent<CannonTotalTests>();}
 static Dictionary<string,Vector2> shots=new Dictionary<string,Vector2>(),inputs=new Dictionary<string,Vector2>();public static void Launched(Component p,Vector2 velocity,Vector2 incoming){shots[p.name]=velocity;inputs[p.name]=incoming;}
 Type pt;Component fan,zhao,manager;Rigidbody2D ball;float scale;int checks,failures;const BindingFlags SP=BindingFlags.Static|BindingFlags.NonPublic,IP=BindingFlags.Instance|BindingFlags.NonPublic;
 void Check(bool pass,string text){checks++;if(!pass)failures++;Debug.Log("ABILITY "+(pass?"PASS ":"FAIL ")+text);}
 Rigidbody2D Body(Component p){return (Rigidbody2D)pt.GetField("rb").GetValue(p);}
 void Move(Component p,Vector2 at){p.transform.position+=(Vector3)(at-Body(p).position);foreach(var b in p.GetComponentsInChildren<Rigidbody2D>()){b.velocity=Vector2.zero;b.angularVelocity=0;}Physics2D.SyncTransforms();}
 float Error(Component p){float e=0;foreach(var j in p.GetComponentsInChildren<HingeJoint2D>())if(j.connectedBody!=null)e=Mathf.Max(e,Vector2.Distance(j.transform.TransformPoint(j.anchor),j.connectedBody.transform.TransformPoint(j.connectedAnchor)));return e;}
 int[] Levels(int total,bool alternate=false){switch(total){case 0:return new int[]{0,0,0};case 8:return new int[]{3,3,2};case 11:return new int[]{4,4,3};case 12:return alternate?new int[]{8,4,0}:new int[]{4,4,4};case 13:return new int[]{5,4,4};case 14:return new int[]{6,4,4};case 16:return new int[]{8,4,4};default:return new int[]{8,8,6};}}
 IEnumerator Scene(int total,int mode=2,bool cannon=true,bool alternate=false){AbilityMode.SetBudget(24);keys.Clear();frames.Clear();shots.Clear();inputs.Clear();bounceChoice=bounces=0;blocker=null;blocked=false;UseAI=false;Time.timeScale=1;ControlBindings.ResetDefaults();AbilityMode.Reset();AbilityMode.Enabled=mode==2;PlayerSkills.Enabled=mode==1;int[] levels=Levels(total,alternate);foreach(var b in AbilityMode.Builds){for(int i=0;i<3;i++)b.Levels[i]=levels[i];b.Purchased=cannon?1<<1:0;}UnityEngine.Random.InitState(981);typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.4f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);manager=FindObjectOfType(pt.Assembly.GetType("GameManager")) as Component;ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;ball.position=new Vector2(0,4*scale);ball.velocity=Vector2.zero;ball.gravityScale=0;foreach(var a in FindObjectsOfType<Animator>())a.cullingMode=AnimatorCullingMode.AlwaysAnimate;GameAIMod.OnBallReset();yield return new WaitForSeconds(.1f);}
 void Setup(Component actor){float dir=actor.name=="Fan"?1:-1;Move(actor,new Vector2(0,Body(actor).position.y));Move(actor==fan?zhao:fan,new Vector2(-dir*4.2f*scale,Body(actor==fan?zhao:fan).position.y));}
 void ContactBall(Component actor,bool rear=false){Vector2 facing=PowerShot.HeadFacing(actor);Collider2D shape=actor.transform.Find("Head").GetComponent<Collider2D>();Vector2 edge=shape.ClosestPoint((Vector2)shape.bounds.center+facing*(rear?-3:3));ball.position=edge+facing*(rear?-1:1)*(ball.GetComponent<Collider2D>().bounds.extents.x-.012f*scale);ball.velocity=facing*(rear?1:-1)*.8f;ball.gravityScale=1;Physics2D.SyncTransforms();}
 void Head(Component actor){PlayerSkills.SetAction((Animator)pt.GetField("anim").GetValue(actor),"Head",actor);}
 void Lean(Component actor,float angle){Vector2 center=Body(actor).position;float c=Mathf.Cos(angle*Mathf.Deg2Rad),s=Mathf.Sin(angle*Mathf.Deg2Rad);foreach(var limb in actor.GetComponentsInChildren<Rigidbody2D>()){Vector2 o=limb.position-center;limb.position=center+new Vector2(o.x*c-o.y*s,o.x*s+o.y*c);limb.rotation+=angle;limb.velocity=Vector2.zero;limb.angularVelocity=0;}Physics2D.SyncTransforms();}
 IEnumerator Velocity(bool isFan,int total,bool alternate=false,bool native=false,bool ordinary=false){yield return Scene(total,native?1:2,!ordinary,alternate);Component actor=isFan?fan:zhao;Setup(actor);ContactBall(actor);Head(actor);for(int i=0;i<15;i++)yield return new WaitForFixedUpdate();Vector2 v=Vector2.zero,prior=Vector2.zero;bool fired=shots.TryGetValue(actor.name,out v)&&inputs.TryGetValue(actor.name,out prior);float expected=ordinary?.85f:native?1f:AbilityMode.CannonSpeed(total),ratio=fired?v.magnitude/PlayerSkills.CannonVelocity(isFan?1:-1,prior).magnitude:0;bool parity=!(total==12||native)||ordinary||Vector2.Distance(v,PlayerSkills.CannonVelocity(isFan?1:-1,prior))<.01f;Check(fired&&Mathf.Abs(ratio-expected)<.01f&&parity&&Error(actor)<.6f,"real header actor="+actor.name+" total="+total+" alternate="+alternate+" native="+native+" ordinary="+ordinary+" ratio="+ratio+" expected="+expected);}
 IEnumerator Rear(bool isFan,int total){yield return Scene(total);Component actor=isFan?fan:zhao;Setup(actor);Lean(actor,(isFan?-1:1)*40);ContactBall(actor,true);Head(actor);for(int i=0;i<10;i++)yield return new WaitForFixedUpdate();Check(!shots.ContainsKey(actor.name),"rear actual contact never launches actor="+actor.name+" total="+total);}
 IEnumerator Gap(bool isFan){yield return Scene(14);Component actor=isFan?fan:zhao;Setup(actor);ball.position=(Vector2)actor.transform.Find("Head").position+Vector2.right*(isFan?1:-1)*1.6f*scale;ball.velocity=Vector2.zero;ball.gravityScale=0;Head(actor);for(int i=0;i<5;i++)yield return new WaitForFixedUpdate();Check(!shots.ContainsKey(actor.name),"no remote high-total header actor="+actor.name);}
 Vector2 Launch(BuildPlayer p,Vector2 incoming){return (Vector2)typeof(BuildPlayer).GetMethod("CannonLaunch",IP).Invoke(p,new object[]{incoming});}
 IEnumerator Paths(bool isFan){yield return Scene(14);Component actor=isFan?fan:zhao;Setup(actor);BuildPlayer owner=actor.GetComponent<BuildPlayer>();int side=isFan?0:1;Collider2D goal=(Collider2D)typeof(BuildPlayer).GetField("goal",IP).GetValue(owner);float dir=isFan?1:-1,radius=ball.GetComponent<Collider2D>().bounds.extents.y;ball.position=new Vector2(0,actor.transform.Find("Head").position.y);Vector2 prior=new Vector2(-dir*.8f,-.5f);float targetY=BallBoundaryGuard.FindGoalCeiling(goal)-radius-.1f*scale,targetX=dir>0?goal.bounds.min.x+radius*.3f:goal.bounds.max.x-radius*.3f;float[] errors=new float[3];for(int i=0;i<3;i++){int[] level=Levels(12+i);for(int j=0;j<3;j++)AbilityMode.Builds[side].Levels[j]=level[j];Vector2 v=Launch(owner,prior);float t=(targetX-ball.position.x)/v.x,cross=ball.position.y+v.y*t+.5f*Physics2D.gravity.y*ball.gravityScale*t*t;errors[i]=Mathf.Abs(cross-targetY);}
 for(int j=0;j<3;j++)AbilityMode.Builds[side].Levels[j]=0;UnityEngine.Random.InitState(617);Vector2 floor=Launch(owner,prior);UnityEngine.Random.InitState(617);Vector2 target=(Vector2)typeof(BuildPlayer).GetMethod("ShotTarget",IP).Invoke(owner,new object[]{0});Vector2 ordinary=(Vector2)typeof(BuildPlayer).GetMethod("AimVelocity",IP).Invoke(owner,new object[]{target,PowerShot.OrdinaryHeaderVelocity(actor,prior).magnitude});Check(errors[2]<.02f&&errors[1]<.1f*scale&&Vector2.Distance(floor,ordinary)<.01f,"flat correction improves at 13/14 and zero equals ordinary aim actor="+actor.name+" errors="+errors[0]+","+errors[1]+","+errors[2]);}
 IEnumerator Air(bool isFan){yield return Scene(14);Component actor=isFan?fan:zhao;Setup(actor);float dir=isFan?1:-1;ball.position=(Vector2)actor.transform.Find("Head").position+new Vector2(dir*.9f*scale,1f*scale);ball.velocity=Vector2.right*-dir*.5f;ball.gravityScale=1;Physics2D.SyncTransforms();float plannedOffset=(float)typeof(BuildPlayer).GetMethod("CannonApproachOffset",IP).Invoke(actor.GetComponent<BuildPlayer>(),null);keys.Add(ControlBindings.Get(isFan,GameControlAction.Jump));keys.Add(ControlBindings.Get(isFan,GameControlAction.Head));float error=0,peak=Body(actor).position.y,start=peak;for(int i=0;i<70;i++){yield return new WaitForFixedUpdate();error=Mathf.Max(error,Error(actor));peak=Mathf.Max(peak,Body(actor).position.y);if(i==3)keys.Clear();}BuildPlayer owner=actor.GetComponent<BuildPlayer>();float offset=(float)typeof(BuildPlayer).GetMethod("CannonApproachOffset",IP).Invoke(owner,null);Check(peak>start+.2f*scale&&shots.ContainsKey(actor.name)&&plannedOffset*dir>0&&error<.6f,"real jump plus head reaches forehead contact actor="+actor.name+" shot="+shots.ContainsKey(actor.name)+" rise="+(peak-start)+" joints="+error);}
 IEnumerator Goal(bool isFan,int total,bool bounce){yield return Scene(total);Component actor=isFan?fan:zhao;Setup(actor);bounceChoice=bounce?1:0;FieldInfo score=manager.GetType().GetField(isFan?"p1Score":"p2Score");int before=(int)score.GetValue(manager);ContactBall(actor);Head(actor);for(int i=0;i<60&&(int)score.GetValue(manager)==before;i++)yield return new WaitForFixedUpdate();Check(shots.ContainsKey(actor.name)&&(int)score.GetValue(manager)>before&&(bounce?bounces==1:bounces==0),"high-total actual header enters native goal actor="+actor.name+" total="+total+" bounce="+bounce+" floorContacts="+bounces);}
 IEnumerator Block(bool isFan){yield return Scene(16);Component actor=isFan?fan:zhao,other=isFan?zhao:fan;Setup(actor);blocker=other.name;bounceChoice=1;ContactBall(actor);Head(actor);bool placed=false;for(int i=0;i<70;i++){yield return new WaitForFixedUpdate();if(!placed&&bounces>0){Move(other,ball.position+ball.velocity*.025f);placed=true;}}bool released=typeof(BuildPlayer).GetField("cannonFlightOwner",SP).GetValue(null)==null;Check(bounces==1&&blocked&&released,"actual late defender contact releases bounce guidance actor="+actor.name+" contacts="+bounces+" blocked="+blocked+" released="+released);}
 IEnumerator Bypass(bool isFan){yield return Scene(16);Component actor=isFan?fan:zhao,other=isFan?zhao:fan;Setup(actor);blocker=other.name;bounceChoice=1;Move(other,new Vector2((isFan?1:-1)*2.2f*scale,Body(other).position.y+2.3f*scale));ContactBall(actor);Head(actor);FieldInfo score=manager.GetType().GetField(isFan?"p1Score":"p2Score");int before=(int)score.GetValue(manager);for(int i=0;i<60&&(int)score.GetValue(manager)==before;i++)yield return new WaitForFixedUpdate();Check(bounces==1&&!blocked&&(isFan?bouncePosition.x<Body(other).position.x:bouncePosition.x>Body(other).position.x)&&(int)score.GetValue(manager)>before,"planned bounce bypasses real airborne defender and enters goal actor="+actor.name+" contacts="+bounces+" blocked="+blocked+" goal="+((int)score.GetValue(manager)>before));}
 IEnumerator Spacing(bool isFan){
  yield return Scene(12);Component actor=isFan?fan:zhao,other=isFan?zhao:fan;Setup(actor);ContactBall(actor);float dir=isFan?1:-1,range=PowerShot.ShootingSkillRange(actor);Move(other,new Vector2(dir*(range-.08f*scale),Body(other).position.y));bool near=!PowerShot.ShootingSkillSpace(actor);Move(other,new Vector2(dir*(range+.08f*scale),Body(other).position.y));bool far=PowerShot.ShootingSkillSpace(actor);Check(range>0&&near&&far,"shooting skill threshold follows actual pitch eighth actor="+actor.name);
  AbilityMode.Builds[isFan?0:1].Purchased=(1<<4)|(1<<5);var owner=actor.GetComponent<BuildPlayer>();var power=typeof(BuildPlayer).GetField("power",IP);var strike=typeof(BuildPlayer).GetMethod("Strike",IP);var effects=(float[])typeof(BuildPlayer).GetField("effects",IP).GetValue(owner);Move(other,new Vector2(dir*.45f*scale,Body(other).position.y));power.SetValue(owner,false);strike.Invoke(owner,null);power.SetValue(owner,true);strike.Invoke(owner,null);Check(effects[4]<0&&effects[5]<0,"allocated leaf and burst cannot activate in close contest actor="+actor.name);
  Move(other,new Vector2(dir*(range+.2f*scale),Body(other).position.y));power.SetValue(owner,false);strike.Invoke(owner,null);power.SetValue(owner,true);strike.Invoke(owner,null);Check(effects[4]>=0&&effects[5]>=0,"allocated leaf and burst activate beyond eighth pitch actor="+actor.name);
  yield return Scene(12,1);actor=isFan?fan:zhao;other=isFan?zhao:fan;Setup(actor);ContactBall(actor);range=PowerShot.ShootingSkillRange(actor);var native=actor.GetComponent<PlayerSkills>();var volley=typeof(PlayerSkills).GetMethod("HasVolleySeparation",IP);var burst=typeof(PlayerSkills).GetMethod("CanBurst",IP);var goal=typeof(PlayerSkills).GetMethod("FindCurveGoal",IP).Invoke(native,null);Move(other,new Vector2(dir*(range-.08f*scale),Body(other).position.y));near=!(bool)volley.Invoke(native,new object[]{goal})&&!(bool)burst.Invoke(native,null);Move(other,new Vector2(dir*(range+.08f*scale),Body(other).position.y));far=(bool)volley.Invoke(native,new object[]{goal})&&(bool)burst.Invoke(native,null);Check(near&&far,"native special-mode leaf and burst share distance gate actor="+actor.name+" near="+near+" far="+far+" range="+range);
 }
 void CaptureLottery(Canvas canvas){
  var renderers=UnityEngine.Object.FindObjectsOfType<Renderer>();foreach(var renderer in renderers)renderer.enabled=false;var obj=new GameObject("Lottery Capture Camera",typeof(Camera));var camera=obj.GetComponent<Camera>();camera.orthographic=true;camera.orthographicSize=5;camera.transform.position=new Vector3(0,0,-30);camera.nearClipPlane=.01f;camera.farClipPlane=100;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.05f,.09f);camera.enabled=false;var target=new RenderTexture(1280,720,24);camera.targetTexture=target;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();camera.Render();var previous=RenderTexture.active;RenderTexture.active=target;var photo=new Texture2D(1280,720,TextureFormat.RGB24,false);photo.ReadPixels(new Rect(0,0,1280,720),0,0);photo.Apply();System.IO.File.WriteAllBytes(System.IO.Path.Combine(Application.dataPath,"..","老虎机抽签页.png"),photo.EncodeToPNG());RenderTexture.active=previous;canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.worldCamera=null;camera.targetTexture=null;target.Release();UnityEngine.Object.Destroy(photo);UnityEngine.Object.Destroy(target);UnityEngine.Object.Destroy(obj);foreach(var renderer in renderers)if(renderer!=null)renderer.enabled=true;
 }
 IEnumerator Lottery(){
  AbilityMode.ResetLottery();UnityEngine.Random.InitState(179);int first=AbilityMode.DrawBudget();bool locked=true;for(int i=0;i<20;i++)locked&=AbilityMode.DrawBudget()==first;Check(locked&&AbilityMode.LotteryDrawn&&first>=12&&first<=24,"match draw locks after one use");
  bool range=true,min=false,max=false;for(int i=0;i<90;i++){AbilityMode.ResetLottery();int n=AbilityMode.DrawBudget();range&=n>=12&&n<=24;min|=n==12;max|=n==24;}AbilityMode.ResetLottery();Check(range&&min&&max&&AbilityMode.Builds[0].Used==12&&!AbilityMode.LotteryDrawn,"lottery includes both endpoints and new match restores default build");
  var existing=UnityEngine.Object.FindObjectOfType<Canvas>();var prototype=existing.GetComponentInChildren<UnityEngine.UI.Button>(true);var canvasObject=new GameObject("Lottery Test Canvas",typeof(Canvas),typeof(UnityEngine.UI.CanvasScaler),typeof(UnityEngine.UI.GraphicRaycaster));var canvas=canvasObject.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=1000;AbilitySetupPanel.Open(canvas.transform,prototype,0,delegate{},delegate{});yield return null;var panel=UnityEngine.Object.FindObjectOfType<AbilitySetupPanel>();var draw=(UnityEngine.UI.Button)typeof(AbilitySetupPanel).GetField("lotteryDraw",IP).GetValue(panel);draw.onClick.Invoke();int n1=AbilityMode.Budget;draw.onClick.Invoke();yield return new WaitForSecondsRealtime(2.35f);CaptureLottery(canvas);yield return new WaitForSecondsRealtime(.25f);var go=(UnityEngine.UI.Button)typeof(AbilitySetupPanel).GetField("lotteryContinue",IP).GetValue(panel);var digits=(UnityEngine.UI.Text[])typeof(AbilitySetupPanel).GetField("reelDigits",IP).GetValue(panel);Check(panel.gameObject.activeInHierarchy&&AbilityMode.Budget==n1&&!draw.gameObject.activeSelf&&go.gameObject.activeSelf&&digits[0].text+digits[1].text==n1.ToString(),"slot animation stops on locked result and disables repeat draw");
  go.onClick.Invoke();yield return null;bool budgetLabel=false;foreach(var t in panel.GetComponentsInChildren<UnityEngine.UI.Text>())if(t.text.Contains("本局共 "+n1+" 点"))budgetLabel=true;UnityEngine.Object.Destroy(panel.gameObject);yield return null;AbilitySetupPanel.Open(canvas.transform,prototype,0,delegate{},delegate{});yield return null;panel=UnityEngine.Object.FindObjectOfType<AbilitySetupPanel>();draw=(UnityEngine.UI.Button)typeof(AbilitySetupPanel).GetField("lotteryDraw",IP).GetValue(panel);Check(budgetLabel&&!draw.gameObject.activeSelf&&AbilityMode.Budget==n1,"allocation uses drawn budget and reopening cannot redraw");UnityEngine.Object.Destroy(panel.gameObject);UnityEngine.Object.Destroy(canvasObject);yield return null;
 }
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=120;QualitySettings.vSyncCount=0;AudioListener.volume=0;yield return new WaitForSeconds(.2f);if(PreviewOnly){yield return Scene(12);yield return Lottery();Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);yield break;}foreach(bool actor in new bool[]{true,false}){foreach(int total in new int[]{0,8,11,12,13,14,16,22})yield return Velocity(actor,total);yield return Velocity(actor,12,true);yield return Velocity(actor,12,false,false,true);yield return Rear(actor,0);yield return Rear(actor,14);yield return Gap(actor);yield return Paths(actor);yield return Air(actor);foreach(int high in new int[]{13,14,22})foreach(bool bounce in new bool[]{false,true})yield return Goal(actor,high,bounce);yield return Block(actor);yield return Bypass(actor);yield return Spacing(actor);}yield return Velocity(true,12,false,true);yield return Lottery();bool valid=equalChance;for(int total=0;total<=24;total++){float expected=total>12?1+.5f*(Mathf.Min(14,total)-12):1-.0125f*(12-total);valid&=Mathf.Abs(AbilityMode.CannonSpeed(total)-expected)<.001f;}AbilityMode.Reset();var b=AbilityMode.Builds[0];AbilityMode.SetBudget(24);b.Levels[0]=8;b.Levels[1]=8;b.Levels[2]=6;b.Purchased=1<<1;valid&=b.Valid&&b.Used==24&&!b.Change(0,1);Check(valid,"speed bands keep exact additive formula, ordinary floor and 24-point lottery maximum and 14-point cap");Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);}
 void Update(){if(Time.realtimeSinceStartup>130){Debug.LogError("ABILITY TIMEOUT");Application.Quit(2);}}
